/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { DiagMatrix, DiagonalMatrix, DiagonalOf, Identity, KroneckerDelta, MatMul, Matrix, MatrixElement, MatrixSymbol, Mul, Q, Sym, Transpose, ask, diagonalizeVector, rational, subs, symbols } from '../../../src';
import { at, sympyMatches, sympyStr } from '../../sympy-str';

describe("doctests of sympy.matrices.expressions.diagonal", () => {
  it("D[1, 2]", () => {
    expect(sympyStr(DiagonalMatrix(new MatrixSymbol('x', rational(2), rational(3))).at(1, 2))).toBe('0');
  });
  it("D[1, 1]", () => {
    expect(sympyStr(DiagonalMatrix(new MatrixSymbol('x', rational(2), rational(3))).at(1, 1))).toBe('x[1, 1]');
  });
  it("D.diagonal_length", () => {
    expect(sympyStr(rational(2))).toBe('2');
  });
  it("DiagonalMatrix(MatrixSymbol('x', n + 1, n)).diagonal_length", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(n)).toBe('n');
  });
  it("tall.diagonal_length", () => {
    expect(sympyStr(rational(3))).toBe('3');
  });
  it("tall[10, 1]", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(DiagonalMatrix(new MatrixSymbol('x', n, rational(3))).at(10, 1))).toBe('0');
  });
  it("diag.shape", () => {
    const v1 = rational(2);
    expect(sympyMatches([v1, at(DiagonalOf(new MatrixSymbol('x', v1, rational(3))).shape, 1)], '(2, 1)')).toBe(true);
  });
  it("diag.diagonal_length", () => {
    expect(sympyStr(rational(2))).toBe('2');
  });
  it("DiagonalOf(MatrixSymbol('x', n + 1, n)).diagonal_length", () => {
    const n = new Sym('n', { integer: true });
    expect(sympyStr(n)).toBe('n');
  });
  it("dtall.diagonal_length", () => {
    expect(sympyStr(rational(3))).toBe('3');
  });
});

